SELECT day, pv, uv
FROM link_stats_daily
WHERE tenant_id = #{param1}
  AND link_id = #{param2}
  AND day >= #{param3}
  AND day <= #{param4}
ORDER BY day ASC

SELECT day, SUM(pv) AS pv, SUM(uv) AS uv
FROM link_stats_daily
WHERE tenant_id = #{param1}
  AND day >= #{param2}
  AND day <= #{param3}
GROUP BY day
ORDER BY day ASC

SELECT COALESCE(SUM(pv), 0) AS total_pv
FROM link_stats_dim_daily
WHERE tenant_id = #{param1}
  AND link_id = #{param2}
  AND day >= #{param3}
  AND day <= #{param4}
  AND dim_type = #{param5}

SELECT dim_value, SUM(pv) AS pv, SUM(uv) AS uv
FROM link_stats_dim_daily
WHERE tenant_id = #{param1}
  AND link_id = #{param2}
  AND day >= #{param3}
  AND day <= #{param4}
  AND dim_type = #{param5}
GROUP BY dim_value
ORDER BY pv DESC, uv DESC, dim_value ASC
LIMIT #{param6}

SELECT occurred_at, request_id, ip_hash,
       ua_raw, ua_family, os_family, device_type,
       referer_domain, language,
       utm_source, utm_medium, utm_campaign
FROM link_visit_events
WHERE tenant_id = #{param1}
  AND link_id = #{param2}
  AND occurred_at >= #{param3}
  AND occurred_at <= #{param4}
ORDER BY occurred_at DESC, id DESC
LIMIT #{param5}
